package com.projexa.coaching.attendance.controller;
import com.projexa.coaching.common.tenant.TenantContextHolder; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import com.projexa.coaching.common.security.ResourceAccess; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/attendance") public class AttendanceController {private final JdbcTemplate db; private final ResourceAccess access; public AttendanceController(JdbcTemplate db, ResourceAccess access){this.db=db; this.access=access;}
@PostMapping("/sessions/{sessionId}/check-in") @PreAuthorize("hasRole('STUDENT') or hasRole('INSTITUTE_OWNER') or hasRole('INSTITUTE_ADMIN')") public Map<String,Object> checkIn(@PathVariable UUID sessionId,@RequestBody CheckIn req, Authentication auth){UUID t=TenantContextHolder.getRequired(); access.requireOwnStudent(t, req.studentId(), auth);if(isRestricted(req.studentId(),t))return Map.of("allowed",false,"code","FEE_OVERDUE","message","Attendance self check-in is restricted until outstanding fees are cleared");db.update("insert into attendance_records(id,tenant_id,session_id,student_id,status) values(?,?,?,?,?) on conflict(session_id,student_id) do update set status=excluded.status,marked_at=now()",UUID.randomUUID(),t,sessionId,req.studentId(),"PRESENT");return Map.of("allowed",true,"status","PRESENT");}
@PostMapping("/sessions/{sessionId}/records") @PreAuthorize("hasAuthority('attendance.manage')") public Map<String,Object> mark(@PathVariable UUID sessionId,@RequestBody Mark req){UUID t=TenantContextHolder.getRequired();db.update("insert into attendance_records(id,tenant_id,session_id,student_id,status) values(?,?,?,?,?) on conflict(session_id,student_id) do update set status=excluded.status,marked_at=now()",UUID.randomUUID(),t,sessionId,req.studentId(),req.status());return Map.of("updated",true);}
private boolean isRestricted(UUID student,UUID t){try{Map<String,Object> s=db.queryForMap("select settings from tenant_settings where tenant_id=?",t);String json=String.valueOf(s.get("settings"));if(!json.contains("feeAttendanceRestriction")||!json.contains("\"enabled\":true"))return false;Integer manual=db.queryForObject("select count(*) from student_attendance_restrictions where tenant_id=? and student_id=? and active=true",Integer.class,t,student); if(manual!=null&&manual>0)return true; Integer overdue=db.queryForObject("select count(*) from invoices where tenant_id=? and student_id=? and status in ('UNPAID','PARTIALLY_PAID') and due_date<current_date",Integer.class,t,student);return overdue!=null&&overdue>0;}catch(Exception e){throw new IllegalStateException("Unable to verify attendance restriction policy", e);}}
public record CheckIn(UUID studentId){} public record Mark(UUID studentId,String status){}
}
